export function createAxisTicks(axis: Axis, tickModel: AxisBaseModel): {
    ticks: number[],
    tickCategoryInterval?: number
} {
    const customValues = (tickModel as unknown as Model<AxisTickOption>).get('customValues');
    if (customValues) {
        return { ticks: parseCustomValues(axis, customValues) };
    }
    // Only ordinal scale support tick interval
    return axis.type === 'category'
        ? makeCategoryTicks(axis, tickModel)
        : {ticks: zrUtil.map(axis.scale.getTicks(), tick => tick.value) };
}

/**
 * Parse the user specified `customValues` to the inner tick values
 * (the ordinal number for ordinal scale, the numeric value otherwise),
 * and discard the values that are out of the axis extent.
 */
function parseCustomValues(axis: Axis, customValues: (number | string | Date)[]): number[] {
    const scale = axis.scale;
    const extent = scale.getExtent();
    const result: number[] = [];
    zrUtil.each(customValues, function (val) {
        const tickValue = scale.parse(val);
        // NaN is filtered out by the comparison as well.
        if (tickValue >= extent[0] && tickValue <= extent[1]) {
            result.push(tickValue);
        }
    });
    return result;
}

/**
 * Make labels at the `axisLabel.customValues` if specified,
 * otherwise return `null` to keep the default behavior.
 */
function makeAxisLabelsFromCustomValues(axis: Axis): ReturnType<typeof createAxisLabels> {
    const labelModel = axis.getLabelModel();
    const customValues = labelModel.get('customValues');
    if (!customValues) {
        return null;
    }
    // Labels are always made by the normal label formatter, so that,
    // for example, time axis labels are formatted as expected.
    const labelFormatter = makeLabelFormatter(axis);
    return {
        labels: zrUtil.map(parseCustomValues(axis, customValues), function (tickValue, idx) {
            const tickObj = { value: tickValue };
            return {
                formattedLabel: labelFormatter(tickObj, idx),
                rawLabel: axis.scale.getLabel(tickObj),
                tickValue: tickValue
            };
        })
    };
}

function makeCategoryLabels(axis: Axis) {
    const labelModel = axis.getLabelModel();
    const result = makeCategoryLabelsActually(axis, labelModel);

    return (!labelModel.get('show') || axis.scale.isBlank())
        ? {labels: [], labelCategoryInterval: result.labelCategoryInterval}
        : result;
}

function makeCategoryLabelsActually(axis: Axis, labelModel: Model<AxisBaseOption['axisLabel']>) {
    const labelsCache = getListCache(axis, 'labels');
    const optionLabelInterval = getOptionCategoryInterval(labelModel);
    const result = listCacheGet(labelsCache, optionLabelInterval as CacheKey);

    if (result) {
        return result;
    }

    let labels;
    let numericLabelInterval;

    if (zrUtil.isFunction(optionLabelInterval)) {
        labels = makeLabelsByCustomizedCategoryInterval(axis, optionLabelInterval);
    }
    else {
        numericLabelInterval = optionLabelInterval === 'auto'
            ? makeAutoCategoryInterval(axis) : optionLabelInterval;
        labels = makeLabelsByNumericCategoryInterval(axis, numericLabelInterval);
    }

